contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(uint depositAmount, uint cashoutAmount) public payable {
        require(depositAmount > c.MinDeposit(), "deposit must exceed MinDeposit");
        require(address(this).balance >= depositAmount, "not enough balance");

        uint beforeBalance = c.balances(address(this));
        c.Deposit{value: depositAmount}();
        uint afterDeposit = c.balances(address(this));

        bool cashoutReverted;
        uint afterCashout;

        if (cashoutAmount > afterDeposit) {
            try c.CashOut(cashoutAmount) {
                cashoutReverted = false;
                afterCashout = c.balances(address(this));
            } catch {
                cashoutReverted = true;
                afterCashout = c.balances(address(this));
            }
        } else {
            c.CashOut(cashoutAmount);
            cashoutReverted = false;
            afterCashout = c.balances(address(this));
        }

        assert(
            afterDeposit == beforeBalance + depositAmount &&
            (cashoutReverted ? afterCashout == afterDeposit : afterCashout == afterDeposit - cashoutAmount)
        );
    }

    receive() external payable {}
}

