    C c;

    constructor(C _c) { c = _c; }

    function run(uint amount) public payable {
        require(address(this).balance >= amount, "not enough balance");
        require(c.MinDeposit() == 0, "MinDeposit must be 0 for this test");

        uint beforeBalance = c.balances(address(this));
        uint beforeContractBalance = address(c).balance;

        c.Deposit{value: amount}();

        uint afterBalance = c.balances(address(this));
        uint afterContractBalance = address(c).balance;

        assert(
            afterBalance == beforeBalance + amount &&
            afterContractBalance == beforeContractBalance + amount
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(uint amount) public payable {
        // Parameter precondition: only test amounts strictly greater than the current MinDeposit,
        // because Deposit only modifies state when msg.value > MinDeposit.
        require(amount > c.MinDeposit(), "amount must exceed MinDeposit");
        require(address(this).balance >= amount, "not enough balance");

