contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint depositAmount, uint cashOutAmount) public payable {
        require(address(this).balance >= depositAmount + cashOutAmount);

        c.Deposit{value: depositAmount}();

        uint balBefore = c.balances(address(this));
        uint cEtherBefore = address(c).balance;
        uint thisEtherBefore = address(this).balance;

        bool reverted;
        try c.CashOut(cashOutAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint balAfter = c.balances(address(this));
        uint cEtherAfter = address(c).balance;
        uint thisEtherAfter = address(this).balance;

        assert(
            (reverted && balAfter == balBefore && cEtherAfter == cEtherBefore && thisEtherAfter == thisEtherBefore) ||
            (!reverted && balAfter == balBefore - cashOutAmount && cEtherAfter == cEtherBefore - cashOutAmount && thisEtherAfter == thisEtherBefore + cashOutAmount)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint depositAmount) public payable {
        require(address(this).balance >= depositAmount);

        uint before = c.balances(address(this));

        c.Deposit{value: depositAmount}();

        uint afterBal = c.balances(address(this));

        if (depositAmount > c.MinDeposit()) {
            assert(afterBal == before + depositAmount);
        } else {
            assert(afterBal == before);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint depositAmount) public payable {
        require(address(this).balance >= depositAmount);

