            try c.CashOut(cashOutAmount) { cashOutReverted = false; }
            catch { cashOutReverted = true; }
        }

        if (cashOutAmount <= afterBalance && !cashOutReverted) {
            assert(
                c.balances(address(this)) == afterBalance - cashOutAmount &&
                address(c).balance == afterContractBalance - cashOutAmount
            );
        } else {
            assert(
                afterBalance == beforeBalance + depositAmount &&
                afterContractBalance == beforeContractBalance + depositAmount &&
                c.balances(address(this)) == afterBalance &&
                address(c).balance == afterContractBalance
            );
        }
    }

    receive() external payable {}
}

